    msmr_check_list = [
        options[opt] == "MSMR"
        for opt in ["open-circuit potential", "particle", "intercalation kinetics"]
    ]
    if (
        options["working electrode"] == "both"
        and any(msmr_check_list)
        and not all(msmr_check_list)
