import pybamm

from . import BaseHysteresisOpenCircuitPotential


class CurrentSigmoidOpenCircuitPotential(BaseHysteresisOpenCircuitPotential):
    def __init__(
        self, param, domain, reaction, options, phase="primary", x_average=False
    ):
        super().__init__(
            param, domain, reaction, options=options, phase=phase, x_average=x_average
        )
        pybamm.citations.register("Ai2022")

    def get_coupled_variables(self, variables):
        domain, Domain = self.domain_Domain
        domain_options = getattr(self.options, domain)
        phase_name = self.phase_name

        # Set hysteresis state
        current = variables["Total current density [A.m-2]"]
        k = 100

        if Domain == "Positive":
            lithiation_current = current
        elif Domain == "Negative":
            lithiation_current = -current

        h_x_av = 1 - 2 * pybamm.sigmoid(0, lithiation_current, k)
        h = pybamm.FullBroadcast(
            h_x_av,
            [f"{domain} electrode"],
            auxiliary_domains={"secondary": "current collector"},
        )
        variables.update(
            {
                f"{Domain} electrode {phase_name}hysteresis state": h,
                f"X-averaged {domain} electrode {phase_name}hysteresis state": h_x_av,
            }
        )
        if domain_options["particle size"] == "distribution":
            h_dist = pybamm.PrimaryBroadcast(h, [f"{domain} {phase_name}particle size"])
            h_dist_x_av = pybamm.x_average(h_dist)
            variables.update(
                {
                    f"{Domain} electrode {phase_name}hysteresis state distribution": h_dist,
                    f"X-averaged {domain} electrode {phase_name}hysteresis state distribution": h_dist_x_av,
                }
            )

        # Get single-state hysteresis variables
        variables.update(self._get_coupled_variables(variables))

        return variables

    def set_initial_conditions(self, variables):
        pass

    def positive(self):
        "Returns the options for the positive electrode"
        # index 1 in a 2-tuple for the positive electrode
        return BatteryModelDomainOptions(self.items(), 1)


class BatteryModelDomainOptions(dict):
    def __init__(self, dict_items, index):
        super().__init__(dict_items)
        self.index = index

    def __getitem__(self, key):
        options = super().__getitem__(key)
        if isinstance(options, str):
            return options
        else:
            # 2-tuple, first is negative domain, second is positive domain
            return options[self.index]

    @property
    def primary(self):
        return BatteryModelPhaseOptions(self, 0)

    @property
    def secondary(self):
        return BatteryModelPhaseOptions(self, 1)


class BatteryModelPhaseOptions(dict):
    def __init__(self, domain_options, index):
        super().__init__(domain_options.items())
        self.domain_options = domain_options
        self.index = index

    def __getitem__(self, key):
        options = self.domain_options.__getitem__(key)
        if isinstance(options, str):
            return options
        else:
            # 2-tuple, first is primary phase, second is secondary phase
            return options[self.index]


class BaseBatteryModel(pybamm.BaseModel):
    """
    Base model class with some default settings and required variables

    Parameters
    ----------
    options : dict-like, optional
        A dictionary of options to be passed to the model. If this is a dict (and not
        a subtype of dict), it will be processed by :class:`pybamm.BatteryModelOptions`
        to ensure that the options are valid. If this is a subtype of dict, it is
        assumed that the options have already been processed and are valid. This allows
        for the use of custom options classes. The default options are given by
        :class:`pybamm.BatteryModelOptions`.
    name : str, optional
        The name of the model. The default is "Unnamed battery model".
    """

    def __init__(self, options=None, name="Unnamed battery model"):
        super().__init__(name)
        self.options = options

    @classmethod
    def deserialise(cls, properties: dict):
        """
        Create a model instance from a serialised object.
        """

        # append the model name with _saved to differentiate

        # Size-averaged flux variables
        D_eff = pybamm.size_average(D_eff)
        R = pybamm.SpatialVariable("R", domains=D_eff.domains)
        f_a_dist = self.phase_param.f_a_dist(R)
        N_s = pybamm.Integral(f_a_dist * N_s, R)
    variables.update(self._get_standard_diffusivity_variables(D_eff))
    variables.update(self._get_standard_flux_variables(N_s))

    return variables

def set_rhs(self, variables):
    domain, Domain = self.domain_Domain
    phase_name = self.phase_name

    if self.size_distribution is False:
        if self.x_average is False:
            c_s = variables[
                f"{Domain} {phase_name}particle concentration [mol.m-3]"
            ]
        else:
            c_s = variables[
                f"X-averaged {domain} {phase_name}particle concentration [mol.m-3]"
            ]
    else:
        if self.x_average is False:
            c_s = variables[
                f"{Domain} {phase_name}particle "
                "concentration distribution [mol.m-3]"
            ]
        else:
            c_s = variables[
                f"X-averaged {domain} {phase_name}particle "
                "concentration distribution [mol.m-3]"
            ]
    self.rhs = {c_s: variables[f"{Domain} {phase_name}particle rhs [mol.m-3.s-1]"]}

def set_boundary_conditions(self, variables):
    domain, Domain = self.domain_Domain
    phase_name = self.phase_name

    if self.size_distribution is False:
        if self.x_average is False:
            c_s = variables[
                f"{Domain} {phase_name}particle concentration [mol.m-3]"
            ]
        else:
            c_s = variables[
                f"X-averaged {domain} {phase_name}particle concentration [mol.m-3]"
            ]
    else:
        if self.x_average is False:
            c_s = variables[
                f"{Domain} {phase_name}particle "
                "concentration distribution [mol.m-3]"
            ]
        else:
            c_s = variables[
                f"X-averaged {domain} {phase_name}particle "
                "concentration distribution [mol.m-3]"
            ]

    rbc = variables[f"{Domain} {phase_name}particle bc [mol.m-4]"]
    self.boundary_conditions = {
        c_s: {"left": (pybamm.Scalar(0), "Neumann"), "right": (rbc, "Neumann")}
    }

def set_initial_conditions(self, variables):
    domain, Domain = self.domain_Domain
    phase_name = self.phase_name

    c_init = self.phase_param.c_init
    if self.size_distribution is False:
        if self.x_average is False:
            c_s = variables[
                f"{Domain} {phase_name}particle concentration [mol.m-3]"
            ]
        else:
            c_s = variables[
                f"X-averaged {domain} {phase_name}particle concentration [mol.m-3]"
            ]
            c_init = pybamm.x_average(c_init)
    else:
        if self.x_average is False:
            c_s = variables[
                f"{Domain} {phase_name}particle "
                "concentration distribution [mol.m-3]"
            ]
            c_init = pybamm.SecondaryBroadcast(
                c_init, f"{domain} {phase_name}particle size"
            )
        else:
            c_s = variables[
                f"X-averaged {domain} {phase_name}particle "
                "concentration distribution [mol.m-3]"
            ]

            c_init = pybamm.SecondaryBroadcast(
                pybamm.x_average(c_init), f"{domain} {phase_name}particle size"
            )
    self.initial_conditions = {c_s: c_init}

def set_rhs(self, variables):
    # Note: we have to use `pybamm.source(rhs, var)` in the rhs dict so that
    # the scalar source term gets multplied by the correct mass matrix when
    # using this model with 2D current collectors with the finite element
    # method (see #1399)
    domain = self.domain

    if self.size_distribution is False:
        c_s_av = variables[f"Average {domain} particle concentration [mol.m-3]"]
        j_xav = variables[
            f"X-averaged {domain} electrode interfacial current density [A.m-2]"
        ]
        R = variables[f"X-averaged {domain} particle radius [m]"]
    else:
        c_s_av = variables[
            f"Average {domain} particle concentration distribution [mol.m-3]"
        ]
        j_xav = variables[
            f"X-averaged {domain} electrode interfacial "
            "current density distribution [A.m-2]"
        ]
        R = variables[f"X-averaged {domain} particle sizes [m]"]

    # eq 15 of Subramanian2005
    # equivalent to dcdt = -i_cc / (eps * F * L)
    dcdt = -3 * j_xav / self.param.F / R

    if self.size_distribution is False:
        self.rhs = {c_s_av: pybamm.source(dcdt, c_s_av)}
    else:
        self.rhs = {c_s_av: dcdt}

    if self.name == "quartic profile":
        # We solve an extra ODE for the average particle concentration gradient
        q_s_av = variables[
            f"Average {domain} particle concentration gradient [mol.m-4]"
        ]
        D_eff_xav = variables[
            f"X-averaged {domain} particle effective diffusivity [m2.s-1]"
        ]

        # eq 30 of Subramanian2005
        dqdt = (
            -30 * pybamm.surf(D_eff_xav) * q_s_av / R**2
            - 45 / 2 * j_xav / self.param.F / R**2
        )
        self.rhs[q_s_av] = pybamm.source(dqdt, q_s_av)

def set_algebraic(self, variables):
    pass

def set_initial_conditions(self, variables):
    """
    For single or x-averaged particle models, initial conditions can't depend on x
    or r so we take the r- and x-average of the initial conditions.
    """
    domain = self.domain
    c_init = pybamm.x_average(pybamm.r_average(self.phase_param.c_init))

    if self.size_distribution is False:
        c_s_av = variables[f"Average {domain} particle concentration [mol.m-3]"]
    else:
        c_s_av = variables[
            f"Average {domain} particle concentration distribution [mol.m-3]"
        ]
        c_init = c_init = pybamm.PrimaryBroadcast(c_init, f"{domain} particle size")

    self.initial_conditions = {c_s_av: c_init}
    if self.name == "quartic profile":
        # We also need to provide an initial condition for the average
        # concentration gradient
        q_s_av = variables[
            f"Average {domain} particle concentration gradient [mol.m-4]"
        ]
        self.initial_conditions.update({q_s_av: 0})

    return variables

def set_rhs(self, variables):
    domain, Domain = self.domain_Domain

    if self.size_distribution is False:
        c_s_rav = variables[f"R-averaged {domain} particle concentration [mol.m-3]"]
        j = variables[f"{Domain} electrode interfacial current density [A.m-2]"]
        R = variables[f"{Domain} particle radius [m]"]
    else:
        c_s_rav = variables[
            f"R-averaged {domain} particle concentration distribution [mol.m-3]"
        ]
        j = variables[
            f"{Domain} electrode interfacial current density distribution [A.m-2]"
        ]
        R = variables[f"{Domain} particle sizes [m]"]

    self.rhs = {c_s_rav: -3 * j / self.param.F / R}

    if self.name == "quartic profile":
        # We solve an extra ODE for the average particle flux
        q_s_rav = variables[
            f"R-averaged {domain} particle concentration gradient [mol.m-4]"
        ]
        c_s_rav = variables[f"R-averaged {domain} particle concentration [mol.m-3]"]
        D_eff = variables[f"{Domain} particle effective diffusivity [m2.s-1]"]

        # eq 30 of Subramanian2005
        self.rhs.update(
            {
                q_s_rav: -30 * pybamm.r_average(D_eff) * q_s_rav / R**2
                - 45 / 2 * j / self.param.F / R**2
            }
        )

def set_algebraic(self, variables):
    if self.name == "uniform profile":
        # No algebraic equations since we only solve for the average concentration
        return

    domain, Domain = self.domain_Domain

    c_s_surf = variables[f"{Domain} particle surface concentration [mol.m-3]"]
    c_s_rav = variables[f"R-averaged {domain} particle concentration [mol.m-3]"]
    D_eff = variables[f"{Domain} particle effective diffusivity [m2.s-1]"]
    j = variables[f"{Domain} electrode interfacial current density [A.m-2]"]
    R = variables[f"{Domain} particle radius [m]"]

    c_max = self.phase_param.c_max
    T_ref = self.param.T_ref
    D_c_max_scale = self.phase_param.D(c_max, T_ref) * c_max

    if self.name == "quadratic profile":
        # We solve an algebraic equation for the surface concentration
        self.algebraic = {
            c_s_surf: (
                pybamm.surf(D_eff) * (c_s_surf - c_s_rav) + j * R / self.param.F / 5
            )
            / D_c_max_scale
        }

    elif self.name == "quartic profile":
        # We solve a different algebraic equation for the surface concentration
        # that accounts for the average concentration gradient inside the particle
        q_s_rav = variables[
            f"R-averaged {domain} particle concentration gradient [mol.m-4]"
        ]
        # eq 31 of Subramanian2005
        D_c_max_over_R_scale = D_c_max_scale / self.phase_param.R_typ
        self.algebraic = {
            c_s_surf: (
                pybamm.surf(D_eff) * (35 / R * (c_s_surf - c_s_rav) - 8 * q_s_rav)
                + j / self.param.F
            )
            / D_c_max_over_R_scale
        }

def set_initial_conditions(self, variables):
    domain, Domain = self.domain_Domain

    c_init = pybamm.r_average(self.phase_param.c_init)

    if self.size_distribution is False:
        c_s_rav = variables[f"R-averaged {domain} particle concentration [mol.m-3]"]
    else:
        c_s_rav = variables[
            f"R-averaged {domain} particle concentration distribution [mol.m-3]"
        ]
        c_init = pybamm.PrimaryBroadcast(c_init, [f"{domain} particle size"])

    self.initial_conditions = {c_s_rav: c_init}

    if self.name in ["quadratic profile", "quartic profile"]:
        # We also need to provide an initial condition (initial guess for the
        # algebraic solver) for the surface concentration
        c_s_surf = variables[f"{Domain} particle surface concentration [mol.m-3]"]
        self.initial_conditions.update({c_s_surf: c_init})
    if self.name == "quartic profile":
